WITH scored AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, FIRST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, LAST_VALUE(channel) IGNORE NULLS OVER w_recent AS last_known_channel FROM promotions WINDOW w_recent AS (ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, CASE WHEN discount_pct >= 0.36 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'partner' THEN 1 END), 0), 2) AS discount_pct_per_partner, COUNT(DISTINCT id) AS distinct_ids, SUM(discount_pct) AS total_discount_pct, RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', starts_on) ORDER BY ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'partner' THEN 1 END), 0), 2) DESC) AS discount_pct_per_partner_rank FROM scored GROUP BY DATE_TRUNC('MONTH', starts_on), CASE WHEN discount_pct >= 0.36 THEN 'HIGH' ELSE 'LOW' END HAVING total_discount_pct >= 0 ORDER BY activity_month NULLS LAST;
